import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0022: An open theme format; built-ins locked; System follows the OS","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0022-theme-format-and-community-themes.md","filePath":"adrs/0022-theme-format-and-community-themes.md","lastUpdated":1789092097000}`),u={name:`adrs/0022-theme-format-and-community-themes.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[20]||=a(`<h1 id="adr-0022-an-open-theme-format-built-ins-locked-system-follows-the-os" tabindex="-1">ADR-0022: An open theme format; built-ins locked; System follows the OS <a class="header-anchor" href="#adr-0022-an-open-theme-format-built-ins-locked-system-follows-the-os" aria-label="Permalink to “ADR-0022: An open theme format; built-ins locked; System follows the OS”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-08-30 · refines <a href="/adrs/0013-themes-as-data">ADR-0013</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2>`,3),c(`p`,null,[l[1]||=i(`ADR-0013 made `,-1),r(m,{term:`theme`},{default:n(()=>[...l[0]||=[i(`themes`,-1)]]),_:1}),l[2]||=i(` data (`,-1),l[3]||=c(`code`,null,`ThemeSpec`,-1),l[4]||=i(`) and let users edit a single `,-1),l[5]||=c(`code`,null,`~/.goat/config/themes.json`,-1),l[6]||=i(`, where an entry whose id matched a built-in `,-1),l[7]||=c(`strong`,null,`overrode`,-1),l[8]||=i(` it. Three problems as we open up: editing built-ins means a bad edit silently breaks a shipped theme (and there's no clean "reset"); a single array file is awkward to share and can't carry a preview image; and the "System" theme rendered raw macOS window colors, so it didn't look like GOAT at all. We want community themes to be a real, shareable thing.`,-1)]),l[21]||=a(`<h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><strong>The GOAT Theme Format (GTF)</strong>, documented in <a href="/THEMES">docs/THEMES.md</a>, is our own small, versioned JSON. There&#39;s no external app-chrome theme standard worth adopting (VS Code themes are editor-token-centric, base16 is 16 terminal colors); our token model already fits. <code>ThemeSpec</code> gains optional metadata (<code>schema</code>, <code>author</code>, <code>description</code>, <code>preview</code>); colors stay <code>#RRGGBB</code> for legibility.</p>`,2),c(`ul`,null,[c(`li`,null,[l[10]||=c(`strong`,null,`Community themes are folders you own:`,-1),l[11]||=i(),l[12]||=c(`code`,null,`~/.goat/config/themes/<id>/theme.json`,-1),l[13]||=i(` (+ optional `,-1),l[14]||=c(`code`,null,`preview.png`,-1),l[15]||=i(`), mirroring `,-1),r(m,{term:`pen`},{default:n(()=>[...l[9]||=[i(`Pens`,-1)]]),_:1}),l[16]||=i(` (ADR-0019). One theme = one folder = one thing you can zip and share. The app also imports/exports a single pasted `,-1),l[17]||=c(`code`,null,`theme.json`,-1),l[18]||=i(`.`,-1)]),l[19]||=a(`<li><strong>Built-ins are read-only.</strong> They live in code; a user theme whose id collides with a built-in is dropped, never an override. To change a built-in you <strong>Duplicate to Edit</strong> into your own theme. This keeps shipped themes a stable baseline and makes &quot;reset&quot; trivial (delete your copy).</li><li><strong>System follows the OS by adopting a real theme:</strong> Light in light mode, <strong>Midnight</strong> in dark (not raw <code>windowBackgroundColor</code>) so GOAT looks like itself in either mode while still honoring the user&#39;s macOS setting.</li><li>The old single <code>themes.json</code> is migrated once into folders; built-in overrides in it become suffixed user themes so no work is lost.</li>`,3)]),l[22]||=a(`<p>The visual theme builder (gradient editor, per-slot swatches via the OKLCH picker, editable live preview) is <strong>Phase 2</strong>; this ADR is the format + storage + locking + the System fix, plus JSON import/edit and preview images.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Themes are now shareable artifacts with previews, built-ins can&#39;t be broken, and System is on-brand. Authors have a documented format and a reference (<code>Export</code> any built-in). Storage moved from one file to a folder tree; resolution reads built-ins (code) + user folders, never merging the two. Preview images for built-ins ship as bundled assets (<code>theme-preview-&lt;id&gt;</code>); user themes carry their own <code>preview.png</code>.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>Keep the single <code>themes.json</code> + a preview field (rejected: previews are loose, sharing means copying an array entry, and built-ins stay overridable), one-file <code>.goattheme</code> bundles with base64-embedded previews (rejected: bloated and less hand-editable than a folder; reconsider if a one-file share format is ever demanded), adopt VS Code/base16 (rejected: they model editors/terminals, not app chrome), keep System on macOS window colors (rejected: it never looked like GOAT).</p>`,5)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};